/**
 * `VersionHistory` — a collapsible 3-column table of when the default value of a
 * setting changed across ClickHouse versions.
 *
 * Mintlify equivalent of clickhouse-docs's `src/theme/VersionHistory`.
 *
 * Self-contained on purpose: it renders intrinsic elements only and references
 * no component that it does not define itself. This file used to wrap the table
 * in Mintlify's `<Accordion>`, and it was then the only component under
 * `/snippets/components` that the build did not inline into the pages importing
 * it, so every `<VersionHistory .../>` on the autogenerated settings pages was
 * dropped as an unknown component and no version history was published at all.
 * Please keep it free of external references, and keep the styling to neutral
 * greys and `currentColor` so that it reads correctly in both themes.
 *
 * Usage:
 *   import { VersionHistory } from "/snippets/components/VersionHistory/VersionHistory.jsx";
 *
 *   <VersionHistory rows={[
 *     { id: "row-1", items: [
 *       { label: "26.4" },
 *       { label: "0" },
 *       { label: "New setting" }
 *     ]},
 *   ]}/>
 *
 * Each row's `items` is expected to be `[Version, Default value, Comment]`.
 */
export const VersionHistory = ({ rows = [] }) => {
  if (rows.length === 0) {
    return null;
  }

  const headers = ["Version", "Default value", "Comment"];
  const border = "1px solid rgba(128, 128, 128, 0.3)";
  const cell = {
    border,
    padding: "0.25rem 0.5rem",
    textAlign: "start",
    verticalAlign: "top",
  };

  return (
    <details
      className="not-prose"
      style={{
        border,
        borderRadius: "0.5rem",
        margin: "0.5rem 0",
        padding: "0.5rem 0.75rem",
        fontSize: "0.8125rem",
        lineHeight: "1.125rem",
      }}
    >
      <summary style={{ cursor: "pointer", fontWeight: 600, opacity: 0.72 }}>
        Version history
      </summary>
      <table style={{ borderCollapse: "collapse", width: "100%", margin: "0.5rem 0 0" }}>
        <thead>
          <tr>
            {headers.map((header) => (
              <th key={header} style={{ ...cell, fontWeight: 600, opacity: 0.72 }}>
                {header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, row_index) => (
            <tr key={row.id ?? row_index}>
              {(row.items ?? []).map((item, item_index) => (
                <td key={item_index} style={{ ...cell, overflowWrap: "anywhere" }}>
                  {item?.label}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </details>
  );
};

export default VersionHistory;
